SELECT SUM(filing_date LIKE '%2015%') AS y2015, SUM(filing_date LIKE '%2016%') AS y2016, SUM(filing_date LIKE '%2017%') AS y2017, SUM(filing_date LIKE '%2018%') AS y2018, SUM(filing_date LIKE '%2019%') AS y2019, SUM(filing_date LIKE '%2020%') AS y2020, SUM(filing_date LIKE '%2021%') AS y2021, SUM(filing_date LIKE '%2022%') AS y2022, SUM(filing_date LIKE '%2023%') AS y2023, SUM(filing_date LIKE '%2024%') AS y2024, SUM(filing_date IS NULL) AS nulls FROM publicationinfo
